package com.ryanjei.orushio.pve.bootstrap;import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import org.junit.jupiter.api.Test;class WindowsLauncherAssetsTest{@Test void repositoryTopLevelHasOneClickLauncherAndRuntimeIsIgnored()throws Exception{String bat=Files.readString(Path.of("START_SERVER.bat")),ignore=Files.readString(Path.of(".gitignore"));assertTrue(bat.contains("scripts\\start-server.ps1"));assertTrue(bat.contains("pause"));assertTrue(ignore.lines().anyMatch(line->line.equals(".runtime/")));}@Test void launcherBuildsBeforeDeployAndNeverStartsPaperAfterBuildFailure()throws Exception{String script=Files.readString(Path.of("scripts/start-server.ps1"));int build=script.indexOf("build --no-daemon"),failure=script.indexOf("plugin buildに失敗"),deploy=script.indexOf("Copy-Item -LiteralPath $builtJar"),paper=script.indexOf("-jar' $paperJar");assertTrue(build>=0&&build<failure&&failure<deploy&&deploy<paper);assertTrue(script.contains("if ($LASTEXITCODE -ne 0)"));}@Test void launcherPinsAndVerifiesPaperAndUsesOnlyLocalBootstrapUrl()throws Exception{String script=Files.readString(Path.of("scripts/start-server.ps1")),opener=Files.readString(Path.of("scripts/open-admin.ps1"));assertTrue(script.contains("paper-1.21.11-132.jar"));assertTrue(script.contains("5ffef465eeeb5f2a3c23a24419d97c51afd7dbb4923ff42df9a3f58bba1ccfba"));assertTrue(script.contains("Security.Cryptography.SHA256"));assertTrue(opener.contains("http://127.0.0.1:8765/auth/bootstrap?token=*"));assertTrue(opener.indexOf("Remove-Item -LiteralPath $Handoff")<opener.indexOf("Start-Process $url"));assertFalse(script.contains("secrets.yml"));}}
